 function payables(){let list=window.EngefexPayables.groups(state).filter(c=>window.EngefexPayables.groupFilter(state,c,project)),total=D.sum(list,c=>c.amount),paid=D.sum(list,c=>c.paid),overdue=D.sum(list.filter(c=>c.due&&c.due<now),c=>D.costBalance(c));return head('Contas a pagar','Contratações, parcelas, vencimentos e pagamentos vinculados ao orçamento da obra.',button('new:costs','+ Nova conta')+button('csv','Exportar CSV','secondary'))+`<div class="stats">${stat('Comprometido',money(total),'Contratos e parcelas cadastrados')}${stat('Pago',money(paid),'Pagamentos registrados')}${stat('A pagar',money(D.sum(list,c=>D.costBalance(c))),'Saldo após descontos e acréscimos')}${stat('Vencido',money(overdue),'Saldo com vencimento anterior a hoje')}</div>`+tabs('payables',[['open','Em aberto'],['paid','Pagos']])+`<p class="section-note">Pagar quita o saldo com a data de hoje. Clique em Pago para desfazer a baixa e voltar a Em aberto; descontos e acréscimos da baixa também são desfeitos. Use Pagar com desconto para informar outro valor, data ou pagamento parcial. Contas quitadas aparecem em Pagos. Pagamentos parciais continuam em aberto pelo saldo restante. Cada parcela aparece separadamente, com seu valor e vencimento. Pagar ou desfazer a baixa afeta somente a parcela escolhida. Clique no valor para ver o rateio desta parcela entre obras. Os totais consideram as notas encontradas pelos filtros e ambas as abas.</p>`+(window.EngefexPayables?.renderFilters(state,project)||'')+costsTable(payableRows(),tab.payables==='paid'?'Nenhuma conta quitada.':'Nenhuma conta em aberto.')}
